package com.complaintbox.controller; import com.complaintbox.entity.*; import com.complaintbox.service.*; import jakarta.servlet.http.HttpSession; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/student") public class StudentController{final AuthService auth;final ComplaintService c;public StudentController(AuthService a,ComplaintService c){auth=a;this.c=c;}@GetMapping("/dashboard")Object dashboard(HttpSession s){Long id=auth.residentId(s);List<Complaint> rows=c.mine(id);Map<String,Object>stats=Map.of("total",rows.size(),"open",rows.stream().filter(x->x.getStatus()==ComplaintStatus.SUBMITTED||x.getStatus()==ComplaintStatus.ASSIGNED).count(),"inProgress",rows.stream().filter(x->x.getStatus()==ComplaintStatus.IN_PROGRESS).count(),"resolved",rows.stream().filter(x->x.getStatus()==ComplaintStatus.RESOLVED).count());return Map.of("profile",auth.me(s),"stats",stats,"recent",rows.stream().limit(6).map(c::map).toList());}}
